phi.narrate("安全验证页面还没通过，再等一会儿");
phi.sleep(15000);
const o = phi.observe();
return { url: o.url, title: o.title, text: (o.text||"").slice(0,1500), nodes: o.nodes.slice(0,40) };

const before = phi.observe();
const ifr = phi.query("iframe", { fields: ["src", "title"], limit: 10 });
phi.sleep(8000);
const after = phi.observe();
return { iframes: ifr, beforeText: (before.text||"").slice(0,400), afterText: (after.text||"").slice(0,400), title: after.title, nodes: after.nodes.slice(0,20) };

const r = phi.goto("https://www.discogs.com/submit");
phi.sleep(10000);
const o = phi.observe();
return { r, url: o.url, title: o.title, text: (o.text||"").slice(0,1200), nodes: o.nodes.slice(0,30) };

const r = phi.goto("https://www.discogs.com/");
phi.sleep(3000);
const o = phi.observe();
const nodes = o.nodes || [];
const hits = nodes.filter(n => /submit|contribut|add|提交|贡献/i.test((n.name||"") + " " + (n.attr||"")));
const links = phi.query("a", { fields: ["href"], limit: 400 });
return { url: o.url, title: o.title, hits, linkCount: links.total, submitLinks: links.items.filter(l => /submit|contribut/i.test(l.href||"")) };

const o = phi.observe();
const links = phi.query("a", { fields: ["href"], limit: 200 });
return { url: o.url, title: o.title, text: (o.text||"").slice(0,800), links: links.items.map(l => l.href).filter(h => !/^\s*$/.test(h||"")).slice(0,120) };

const r = phi.goto("https://www.discogs.com/submissions");
phi.sleep(4000);
const o = phi.observe();
return { r, url: o.url, title: o.title, text: (o.text||"").slice(0,1500) };

const r = phi.goto("https://www.discogs.com/");
phi.sleep(2500);
const links = phi.query("a", { fields: ["href", "text"], limit: 500 });
const all = links.items;
const hits = all.filter(l => /help|support|contribut|submit|guideline/i.test((l.href||"") + " " + (l.text||"")));
return { url: r.url, total: links.total, hits: hits.slice(0, 40) };

const r = phi.goto("https://support.discogs.com/hc/en-us");
phi.sleep(2500);
const o = phi.observe();
return { r, url: o.url, title: o.title, text: (o.text||"").slice(0,1200) };

const links = phi.query("a", { fields: ["href", "text"], limit: 400 });
const hits = links.items.filter(l => /contribut|submi|database|guideline|quick ?start/i.test((l.href||"") + " " + (l.text||"")));
return { total: links.total, hits: hits.slice(0, 40) };

const r = phi.tabs.open("https://support.discogs.com/hc/en-us/articles/360004016474-Overview-Of-Submission-Guidelines-For-Releases");
phi.sleep(3000);
const o = phi.observe();
return { r, url: o.url, title: o.title, text: (o.text||"").slice(0, 2000) };

const tabs = phi.tabs.list();
// 收起 cookie 提示条，让正文干净可读
let cookieAction = null;
const btns = phi.query("button", { fields: ["text"], limit: 60 }).items.map(b => b.text);
const o1 = phi.observe();
const accept = o1.nodes.find(n => /accept all/i.test(n.name || n.text || ""));
if (accept) { const r = phi.click(accept.ref); cookieAction = { clicked: "Accept All", changed: !!r.changed }; phi.sleep(1500); }
const h1 = phi.query("h1", { limit: 3 }).items.map(x => x.text);
const crumbs = phi.query("ol li a, .breadcrumbs a, nav[aria-label] a", { fields: ["text","href"], limit: 10 }).items;
const t = phi.text();
phi.keep("discogs_submission_overview", {
  tab: "https://support.discogs.com/hc/en-us/articles/360004016474-Overview-Of-Submission-Guidelines-For-Releases",
  pageTitle: "Overview Of Submission Guidelines For Releases – Discogs",
  heading: h1,
  breadcrumb: "Discogs > Database & Contributing > Database Guidelines > Overview Of Submission Guidelines For Releases",
  sections: ["Basic Guidelines","Overview Of General Information","Full Guidelines"],
  lengthChars: t.length
});
return { tabs, cookieAction, h1, crumbs, start: t.slice(0, 600) };

const tabs = phi.tabs.list();
const t = tabs.find(x => x.url.includes("360004016474"));
let state = null;
if (t) {
  phi.tabs.switch(t.tabId);
  const o = phi.observe();
  const txt = phi.text();
  state = {
    url: o.url,
    title: o.title,
    h1: phi.query("h1", { limit: 2 }).items.map(x => x.text),
    visibleTextStart: txt.slice(0, 900)
  };
}
return { tabs, state };

const tabs = phi.tabs.list();
const t = tabs.find(x => x.url.includes("360004016474"));
phi.tabs.switch(t.tabId);
const o = phi.observe();
phi.js(() => window.scrollTo(0, 0));
